(* [comment removed for export] *)
Definition rs_frames (m : mem) (sp : word) (spa ff fp E bs P fb : Z) (mw80 : cell) (tmp gap : list cell)
    (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte) (ob : Z)
    (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr : list cell) : Prop :=
  rs_frame m sp spa ff E bs P fb mw80 tmp gap
  /\ rw_cells bsegs m (bv_unsigned sp + -104) (rs_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)
  /\ rw_cells bsegs m (bv_unsigned sp) fr /\ Z.of_nat (cells_size fr) = 128
  /\ rs_fake m ff fp hw optc j56 ectc j120 ob 248.

(* [comment removed for export] *)
Definition rs_core (C : rsc) (MA R : Z) (sp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v ra : word) (fr : list cell)
    (w : rsw) (s : as_St H) (errv : word) (E : ecv) (tot : Z) (m : mem) (spa ff fp : Z) (mw80 : cell) (tmp gap : list cell)
    (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte) (ob : Z) (XS : list (Z * Z)) : Prop :=
  RWmF C ((2, ff, fp) :: c_LF C) w s errv E m /\ RWp H C MA w /\ al_okR s (ps_A (w_d w)) MA R
  /\ stk bsegs m (c_lo C) spa
  /\ rs_frames m sp spa ff fp (c_E C) (c_bs C) (c_P C) (c_fb C) mw80 tmp gap hw optc j56 ectc j120 ob s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr
  /\ fresh_frame H (c_LF C) 2 ff fp /\ (exists me, as_RFS H (c_LF C) me)     (* [comment removed for export] *)
  /\ Forall (fs_scratch H (c_LF C)) XS
  /\ (forall a, (ff <= a < ff + 256 \/ Z.shiftr ff 3 + 2147450880 <= a < Z.shiftr ff 3 + 2147450880 + 32 \/ a = fp) -> rin_ivs XS a)   (* [comment removed for export] *)
  /\ xpres H (c_LBin C) (c_SP C) (hread_X (c_P C) (c_E C) (c_fb C) (c_stb C) [] [] ++ XS) (c_m0 C) m
  /\ 0 <= tot /\ tot + zlength (w_fds w) + zlength (w_sds w) <= c_N C
  /\ w_nr w <= c_N C - zlength (w_sds w).

(* [comment removed for export] *)
Definition rs_at_put (C : rsc) (MA R : Z) (sp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v ra : word) (fr : list cell) (M0 : Z) (w : rsw)
    (cf : config) : Prop :=
  exists (t0 t1 t2 a4 a5 a6 a7 s5x s6x t3 t4 t5 t6 : word) (m : mem) (s : as_St H) (errv : word) (E : ecv) (tot : Z)
         (spa ff fp : Z) (mw80 : cell) (tmp gap : list cell) (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte) (XS : list (Z * Z)),
    as_VIS H s (cfg_ms cf)
      = rs_ms P_A_BP_PUT (Z_to_bv 64 RS_PUTRET) sp spa (c_gp C) (c_tp C) t0 t1 t2 (c_E C) (wz (c_P C)) (wz (fb_in (w_FB w))) (wz (fb_size (w_FB w))) (wz (c_E C))
              a4 a5 a6 a7 tot (c_fb C) ff s5x s6x t3 t4 t5 t6 (c_F C) (c_fc C) m
    /\ 1 <= fb_size (w_FB w) /\ pc_state (ps_c (w_d w)) <> 11
    /\ as_AKREL H s cf /\ as_MPRES H (c_mo0 C) (cfg_model cf)
    /\ rs_core C MA R sp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v ra fr w s errv E tot m spa ff fp mw80 tmp gap hw optc j56 ectc j120 248 XS
    /\ wM (c_N C) w <= M0.

(* [comment removed for export] *)
Definition rs_at_doread (C : rsc) (MA R : Z) (sp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v ra : word) (fr : list cell) (M0 : Z) (w : rsw)
    (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x t3 t4 t5 t6 : word) (m : mem) (s : as_St H) (errv : word) (E : ecv) (tot : Z)
         (spa ff fp : Z) (mw80 : cell) (tmp gap : list cell) (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte) (XS : list (Z * Z)),
    as_VIS H s (cfg_ms cf)
      = rs_ms RS_DOREAD rax sp spa (c_gp C) (c_tp C) t0 t1 t2 (c_E C) a0 a1 a2 a3 a4 a5 a6 a7 tot (c_fb C) ff s5x s6x t3 t4 t5 t6 (c_F C) (c_fc C) m
    /\ pc_state (ps_c (w_d w)) <> 11
    /\ as_AKREL H s cf /\ as_MPRES H (c_mo0 C) (cfg_model cf)
