(* [comment removed for export] *)
(* [comment removed for export] *)
Definition fwin (ff fp : Z) (iv : Z * Z) : Prop :=
     (ff <= fst iv /\ snd iv <= ff + 256)
  \/ iv = (fp, fp + 1)
  \/ (Z.shiftr ff 3 + 2147450880 <= fst iv /\ snd iv <= Z.shiftr ff 3 + 2147450880 + 32)
  \/ iv = (as_FSB H, as_FSB H + AFS_FLAGS).


(* [comment removed for export] *)
Lemma fs_scratch_popC : forall f LF iv, fs_scratch H (f :: LF) iv -> fs_scratch H LF iv.
Proof.
  intros f LF iv [E|(k & ff & fp & FF & E)]; [left; exact E| right].
  exists k, ff, fp. split; [| exact E]. destruct FF as (A & B & C). split; [exact A|]. split; [exact B|].
  intros g IN. apply C. right. exact IN.
Qed.
Lemma Forall_scratch_popC : forall f LF XS, Forall (fs_scratch H (f :: LF)) XS -> Forall (fs_scratch H LF) XS.
Proof. intros f LF XS FX. eapply Forall_impl; [| exact FX]. intros iv K. eapply fs_scratch_popC. exact K. Qed.


(* [comment removed for export] *)
Lemma fobj_off_block0 : asan_rt_hyps H -> forall s LB m LF m1 O n p A k,
  as_RHEAP H s LB m -> as_RFS H LF m1 -> aobj [] LF O n -> In (p, A, k) LB -> O + n <= A \/ A + k <= O.
Proof.
  intros HH s LB m LF m1 O n p A k RH RF AO IN. destruct AO as [(b & Hb & _)|(f & Hf & H1 & H2)]; [destruct Hb|].
  pose proof (ah_blocks H HH _ _ _ _ RH IN) as (_ & _ & K0 & _ & _ & KF & _). cbn [blk_addr blk_size fst snd] in K0, KF.
  pose proof (proj2 (ah_RFS_range H HH _ _ RF) f Hf) as (_ & F1 & F2 & _). pose proof (fsz_pos' (ff_class f) ltac:(pose proof (proj2 (ah_RFS_range H HH _ _ RF) f Hf) as (K & _); lia)).
  unfold AFS_HDR, AFS_SIZE in *. lia.
Qed.

Section FW.
  Hypothesis HH : asan_rt_hyps H.
  Variables (LF : list fframe) (ff fp : Z).
  Hypothesis FF : fresh_frame H LF 2 ff fp.

  Lemma fwin_nums :
       AIMG_TOP + AFS_HDR <= ff /\ ff + 256 <= aceil /\ ff mod 64 = 0 /\ AIMG_TOP + AFS_FLAGS <= fp /\ fp + 1 <= ff
    /\ as_FSB H + AFS_FLAGS <= fp /\ as_FSB H + AFS_HDR <= ff /\ ff + 256 <= as_FSB H + AFS_SIZE /\ AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil
    /\ Z.shiftr ff 3 + 2147450880 = sh ff /\ 0x800c8800 <= sh ff /\ sh ff + 32 <= sh aceil /\ sh aceil < aceil /\ sh (as_FSB H) <= sh ff
    /\ sh ff + 32 <= sh (as_FSB H + AFS_SIZE) /\ ALOWSH_LO < sh ff /\ sh ff + 32 <= AHI_LO
