  Lemma fwin_client : forall LB iv, fwin ff fp iv -> aclient_write_ok H LB iv.
  Proof.
    intros LB iv FW. pose proof fwin_nums as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & SHFF & SF0 & SF1 & SA & M1 & M2 & _).
    unfold AFS_HDR, AFS_FLAGS, AFS_SIZE in *. destruct iv as [l h].
    destruct FW as [[K1 K2]|[K|[[K1 K2]|K]]]; cbn [fst snd] in *.
    - right; right; right; right; left. cbn [fst snd]. lia.
    - injection K as -> ->. right; right; right; right; left. cbn [fst snd]. lia.
    - right; right; right; right; right; left. cbn [fst snd]. rewrite SHFF in K1, K2. lia.
    - injection K as -> ->. right; right; right; right; left. cbn [fst snd]. lia.
  Qed.

  Lemma fwin_fr : forall iv, fwin ff fp iv -> win_fr ff 32 iv.
  Proof.
    intros iv FW. pose proof fwin_nums as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & SHFF & SF0 & SF1 & SA & M1 & M2 & L2 & SH & SIDE & _).
    unfold AFS_HDR, AFS_FLAGS, AFS_SIZE in *. destruct iv as [l h]. unfold win_fr. cbn [fst snd].
    destruct FW as [[K1 K2]|[K|[[K1 K2]|K]]]; cbn [fst snd] in *.
    - destruct SIDE; [left| right; left]; lia.
    - injection K as -> ->. destruct SIDE; [left| right; left]; lia.
    - right; right. rewrite SHFF in K1, K2. lia.
    - injection K as -> ->. destruct SIDE; [left| right; left]; lia.
  Qed.

  Lemma fwin_stack0 : forall iv, fwin ff fp iv -> stack0_ok iv.
  Proof.
    intros iv FW. pose proof fwin_nums as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & SHFF & SF0 & SF1 & SA & M1 & M2 & L2 & SH & SIDE & APFF & APP1 & APB).
    destruct iv as [l h]. destruct FW as [[K1 K2]|[K|[[K1 K2]|K]]]; cbn [fst snd] in *.
    - eapply stack0_ok_aapp; [exact APFF| exact K1| exact K2].
    - injection K as -> ->. eapply stack0_ok_aapp; [exact APP1| lia| lia].
    - right. cbn [fst snd]. rewrite SHFF in K2. lia.
    - injection K as -> ->. eapply stack0_ok_aapp; [exact APB| lia| unfold AFS_FLAGS, AFS_SIZE; lia].
  Qed.

