  (* [comment removed for export] *)
  Lemma fwinF_client : forall LB W, Forall (fwin ff fp) W -> Forall (aclient_write_ok H LB) W.
  Proof. intros LB W FW. eapply Forall_impl; [| exact FW]. intros iv K. apply fwin_client. exact K. Qed.
  Lemma fwinF_fr : forall W, Forall (fwin ff fp) W -> Forall (win_fr ff 32) W.
  Proof. intros W FW. eapply Forall_impl; [| exact FW]. intros iv K. apply fwin_fr. exact K. Qed.
  Lemma fwinF_stack0 : forall W, Forall (fwin ff fp) W -> Forall stack0_ok W.
  Proof. intros W FW. eapply Forall_impl; [| exact FW]. intros iv K. apply fwin_stack0. exact K. Qed.
  Lemma fwinF_img : forall W A k, Forall (fwin ff fp) W -> A + k <= AIMG_TOP -> disjoint_from W A k.
  Proof.
    induction W as [|[l h] W IH]; intros A k FW HA; cbn; [exact I|].
    split; [left; exact (fwin_img _ _ _ (Forall_inv FW) HA)| apply IH; [exact (Forall_inv_tail FW)| exact HA]].
  Qed.
  Lemma fwinF_stack : forall W A k, Forall (fwin ff fp) W -> aceil <= A -> disjoint_from W A k.
  Proof.
    induction W as [|[l h] W IH]; intros A k FW HA; cbn; [exact I|].
    split; [right; exact (fwin_stack _ _ (Forall_inv FW) HA)| apply IH; [exact (Forall_inv_tail FW)| exact HA]].
  Qed.
  Lemma fwinF_obj : forall W me O n, Forall (fwin ff fp) W -> as_RFS H LF me -> fsobj H LF O n -> aapp O n -> 0 <= n -> disjoint_from W O n.
  Proof.
    induction W as [|[l h] W IH]; intros me O n FW RF FO AP N0; cbn; [exact I|].
    split; [exact (fwin_obj _ _ _ _ RF FO AP N0 (Forall_inv FW))| eapply IH; [exact (Forall_inv_tail FW)| exact RF| exact FO| exact AP| exact N0]].
  Qed.
  Lemma fwinF_obj_sh : forall W me O n, Forall (fwin ff fp) W -> as_RFS H LF me -> fsobj H LF O n -> aapp O n -> 0 <= n -> disjoint_from W (sh O) (nsh n).
  Proof.
    induction W as [|[l h] W IH]; intros me O n FW RF FO AP N0; cbn; [exact I|].
    split; [exact (fwin_obj_sh _ _ _ _ RF FO AP N0 (Forall_inv FW))| eapply IH; [exact (Forall_inv_tail FW)| exact RF| exact FO| exact AP| exact N0]].
  Qed.
  Lemma fwinF_outside_sh : forall W me O n x, Forall (fwin ff fp) W -> as_RFS H LF me -> fsobj H LF O n -> aapp O n -> 0 <= n -> O <= x < O + n -> outside W (sh x).
  Proof.
    induction W as [|[l h] W IH]; intros me O n x FW RF FO AP N0 Hx; cbn; [exact I|].
    split; [exact (fwin_out_sh _ _ _ _ _ RF FO AP N0 Hx (Forall_inv FW))| eapply IH; [exact (Forall_inv_tail FW)| exact RF| exact FO| exact AP| exact N0| exact Hx]].
  Qed.
  Lemma fwinF_blk : forall W me s LB m p A k, Forall (fwin ff fp) W -> as_RFS H LF me -> as_RHEAP H s LB m -> In (p, A, k) LB ->
    disjoint_from W A k /\ disjoint_from W (sh A) (nsh k).
  Proof.
    induction W as [|[l h] W IH]; intros me s LB m p A k FW RF RH IN; cbn; [split; exact I|].
    destruct (fwin_blk _ _ _ _ _ _ _ _ RF RH IN (Forall_inv FW)) as [K1 K2]. destruct (IH _ _ _ _ _ _ _ (Forall_inv_tail FW) RF RH IN) as [K3 K4].
    split; split; assumption.
  Qed.
End FW.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition objwin (hi fb E ff fp : Z) (iv : Z * Z) : Prop :=
     (aceil <= fst iv /\ snd iv <= hi)
  \/ (fb <= fst iv /\ snd iv <= fb + 48)
  \/ (E <= fst iv /\ snd iv <= E + 24)
  \/ iv = (AG_HTTP_CAT, AG_HTTP_CAT + 64)
  \/ fwin ff fp iv.

Lemma disjoint_from_sub : forall W a n a' n', disjoint_from W a n -> a <= a' -> a' + n' <= a + n -> disjoint_from W a' n'.
Proof. induction W as [|[l h] W IH]; intros a n a' n' D H1 H2; cbn in *; [exact I|]. destruct D as [D1 D2]. split; [lia| eapply IH; eauto]. Qed.

Section OW.
  Hypothesis HH : asan_rt_hyps H.
  Variables (LF : list fframe) (ff fp hi fb E : Z) (me : mem).
  Hypothesis FF : fresh_frame H LF 2 ff fp.
  Hypothesis RF0 : as_RFS H LF me.
  Hypothesis APF : aapp fb 48.
  Hypothesis APE : aapp E 24.
  Hypothesis HI : aceil <= hi.

  (* [comment removed for export] *)
  Lemma objwin_obj : forall W O n, Forall (objwin hi fb E ff fp) W -> fsobj H LF O n -> aapp O n -> 0 <= n ->
    (O + n <= fb \/ fb + 48 <= O) -> (O + n <= E \/ E + 24 <= O) -> disjoint_from W O n.
  Proof.
    induction W as [|[l h] W IH]; intros O n FW FO AP N0 DF DE; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact FO| exact AP| exact N0| exact DF| exact DE]].
    pose proof (Forall_inv FW) as K. pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5).
    destruct K as [K|[K|[K|[K|K]]]]; cbn [fst snd] in K.
    - clear - K B2. lia.
    - clear - K DF. lia.
    - clear - K DE. lia.
    - injection K as -> ->. unfold AG_HTTP_CAT, AIMG_TOP in *. clear - B1. lia.
    - exact (fwin_obj HH LF ff fp FF _ _ _ _ RF0 FO AP N0 K).
  Qed.

  (* [comment removed for export] *)
  Lemma objwin_obj_sh : forall W O n, Forall (objwin hi fb E ff fp) W -> fsobj H LF O n -> aapp O n -> 0 <= n -> disjoint_from W (sh O) (nsh n).
  Proof.
    induction W as [|[l h] W IH]; intros O n FW FO AP N0; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact FO| exact AP| exact N0]].
    pose proof (Forall_inv FW) as K. pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5). pose proof aceil_facts as (AF1 & _).
    pose proof (sh_ge_lowsh O ltac:(lia)) as KL. pose proof (sh_nsh_high O n ltac:(lia) N0 ltac:(lia)) as KH.
    pose proof (aapp_not_shadowland _ _ APF) as NF. pose proof (aapp_not_shadowland _ _ APE) as NE.
    destruct K as [K|[K|[K|[K|K]]]]; cbn [fst snd] in K.
    - left. unfold AHI_LO in *. clear - K KH AF1. lia.
    - unfold ALOWSH_LO, AHI_LO in *. clear - K KL KH NF. lia.
    - unfold ALOWSH_LO, AHI_LO in *. clear - K KL KH NE. lia.
    - injection K as -> ->. right. unfold AG_HTTP_CAT, ALOWSH_LO in *. clear - KL. lia.
    - exact (fwin_obj_sh HH LF ff fp FF _ _ _ _ RF0 FO AP N0 K).
  Qed.
  Lemma objwin_out_sh : forall W O n x, Forall (objwin hi fb E ff fp) W -> fsobj H LF O n -> aapp O n -> 0 <= n -> O <= x < O + n -> outside W (sh x).
  Proof.
    induction W as [|[l h] W IH]; intros O n x FW FO AP N0 Hx; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact FO| exact AP| exact N0| exact Hx]].
    pose proof (Forall_inv FW) as K. pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5). pose proof aceil_facts as (AF1 & _).
    pose proof (sh_ge_lowsh x ltac:(lia)) as KL. pose proof (sh_below_app x ltac:(lia)) as KH.
    pose proof (aapp_not_shadowland _ _ APF) as NF. pose proof (aapp_not_shadowland _ _ APE) as NE.
    destruct K as [K|[K|[K|[K|K]]]]; cbn [fst snd] in K.
    - unfold AHI_LO in *. clear - K KH AF1. lia.
    - unfold ALOWSH_LO, AHI_LO in *. clear - K KL KH NF. lia.
    - unfold ALOWSH_LO, AHI_LO in *. clear - K KL KH NE. lia.
    - injection K as -> ->. unfold AG_HTTP_CAT, ALOWSH_LO in *. clear - KL. lia.
    - exact (fwin_out_sh HH LF ff fp FF _ _ _ _ _ RF0 FO AP N0 Hx K).
  Qed.

  (* [comment removed for export] *)
  Lemma objwin_blk : forall W s LB m p A k, Forall (objwin hi fb E ff fp) W -> as_RHEAP H s LB m -> In (p, A, k) LB ->
    aobj [] LF fb 48 -> aobj [] LF E 24 -> disjoint_from W A k /\ disjoint_from W (sh A) (nsh k).
  Proof.
