  (* [comment removed for export] *)
  Lemma objwin_img : forall W A k, Forall (objwin hi fb E ff fp) W -> 0 <= A -> A + k <= AIMG_TOP -> (A + k <= AG_HTTP_CAT \/ AG_HTTP_CAT + 64 <= A) ->
    disjoint_from W A k.
  Proof.
    induction W as [|[l h] W IH]; intros A k FW A0 HA HC; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact A0| exact HA| exact HC]].
    pose proof (Forall_inv FW) as K. pose proof aceil_facts as (AF1 & _).
    pose proof (aapp_bounds _ _ APF ltac:(lia)) as (B1 & _). pose proof (aapp_bounds _ _ APE ltac:(lia)) as (C1 & _).
    destruct K as [K|[K|[K|[K|K]]]]; cbn [fst snd] in K.
    - left. unfold AIMG_TOP in *. clear - K HA AF1. lia.
    - left. clear - K HA B1. lia.
    - left. clear - K HA C1. lia.
    - injection K as -> ->. clear - HC. lia.
    - left. exact (fwin_img LF ff fp FF _ _ _ K HA).
  Qed.

  (* [comment removed for export] *)
  Lemma objwin_hi : forall W A k, Forall (objwin hi fb E ff fp) W -> hi <= A -> disjoint_from W A k.
  Proof.
    induction W as [|[l h] W IH]; intros A k FW HA; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact HA]].
    pose proof (Forall_inv FW) as K. pose proof aceil_facts as (AF1 & _).
    pose proof (aapp_bounds _ _ APF ltac:(lia)) as (_ & B2 & _). pose proof (aapp_bounds _ _ APE ltac:(lia)) as (_ & C2 & _).
    destruct K as [K|[K|[K|[K|K]]]]; cbn [fst snd] in K.
    - right. clear - K HA. lia.
    - right. clear - K HA HI B2. lia.
    - right. clear - K HA HI C2. lia.
    - injection K as -> ->. right. unfold AG_HTTP_CAT in *. clear - HA HI AF1. lia.
    - right. assert (Q : aceil <= A) by (clear - HA HI; lia). exact (fwin_stack LF ff fp FF _ A K Q).
  Qed.

  (* [comment removed for export] *)
  Lemma objwin_fr : forall W, Forall (objwin hi fb E ff fp) W -> Forall (win_fr ff 32) W.
  Proof.
    intros W FW. eapply Forall_impl; [| exact FW]. intros [l h] K. pose proof aceil_facts as (AF1 & _).
    pose proof (aapp_not_shadowland _ _ APF) as NF. pose proof (aapp_not_shadowland _ _ APE) as NE.
    destruct K as [K|[K|[K|[K|K]]]]; cbn [fst snd] in K.
    - right; left. cbn. unfold AHI_LO in *. clear - K AF1. lia.
    - unfold win_fr. cbn [fst snd]. clear - K NF. lia.
    - unfold win_fr. cbn [fst snd]. clear - K NE. lia.
    - injection K as -> ->. left. cbn. unfold AG_HTTP_CAT, ALOWSH_LO. clear. lia.
    - exact (fwin_fr LF ff fp FF _ K).
  Qed.

  Lemma objwin_client : forall W s LB m, Forall (objwin hi fb E ff fp) W -> as_RHEAP H s LB m -> aobj LB LF fb 48 -> aobj LB LF E 24 ->
    Forall (aclient_write_ok H LB) W.
  Proof.
    intros W s LB m FW RH AOF AOE. eapply Forall_impl; [| exact FW]. intros [l h] K.
    destruct K as [K|[K|[K|[K|K]]]]; cbn [fst snd] in K.
    - left. cbn. clear - K. lia.
    - pose proof (proj1 (aobj_write_ok H HH _ _ _ _ _ _ _ RH RF0 (aobj_sub _ _ _ _ l (h - l) AOF ltac:(clear - K; lia) ltac:(clear - K; lia)))) as Q.
      replace (l + (h - l)) with h in Q by lia. exact Q.
    - pose proof (proj1 (aobj_write_ok H HH _ _ _ _ _ _ _ RH RF0 (aobj_sub _ _ _ _ l (h - l) AOE ltac:(clear - K; lia) ltac:(clear - K; lia)))) as Q.
      replace (l + (h - l)) with h in Q by lia. exact Q.
    - injection K as -> ->. right; left. unfold aimg_client_w, ATLS_PRIV_LO, ATP, AG_HTTP_CAT. cbn [fst snd]. right; right; right; left. clear. lia.
    - exact (fwin_client LF ff fp FF LB _ K).
  Qed.
