(* [comment removed for export] *)
Definition qwin (hi ff : Z) (iv : Z * Z) : Prop :=
     (aceil <= fst iv /\ snd iv <= hi)
  \/ (Z.shiftr ff 3 + 2147450880 <= fst iv /\ snd iv <= Z.shiftr ff 3 + 2147450880 + 32).

Section QW.
  Hypothesis HH : asan_rt_hyps H.
  Variables (LF : list fframe) (ff fp hi : Z) (me : mem).
  Hypothesis FF : fresh_frame H LF 2 ff fp.
  Hypothesis RF0 : as_RFS H LF me.
  Hypothesis HI : aceil <= hi.

  Lemma qwin_fwin : forall iv, qwin hi ff iv -> (aceil <= fst iv /\ snd iv <= hi) \/ fwin ff fp iv.
  Proof. intros iv [K|K]; [left; exact K| right]. right; right; left. exact K. Qed.

  Lemma qwin_obj : forall W O n, Forall (qwin hi ff) W -> fsobj H LF O n -> aapp O n -> 0 <= n -> disjoint_from W O n.
  Proof.
    induction W as [|[l h] W IH]; intros O n FW FO AP N0; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact FO| exact AP| exact N0]].
    pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5).
    destruct (qwin_fwin _ (Forall_inv FW)) as [K|K]; [cbn [fst snd] in K; clear - K B2; lia| exact (fwin_obj HH LF ff fp FF _ _ _ _ RF0 FO AP N0 K)].
  Qed.
  Lemma qwin_obj_sh : forall W O n, Forall (qwin hi ff) W -> fsobj H LF O n -> aapp O n -> 0 <= n -> disjoint_from W (sh O) (nsh n).
  Proof.
    induction W as [|[l h] W IH]; intros O n FW FO AP N0; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact FO| exact AP| exact N0]].
    pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5). pose proof aceil_facts as (AF1 & _).
    pose proof (sh_nsh_high O n ltac:(lia) N0 ltac:(lia)) as KH.
    destruct (qwin_fwin _ (Forall_inv FW)) as [K|K]; [cbn [fst snd] in K; left; unfold AHI_LO in *; clear - K KH AF1; lia| exact (fwin_obj_sh HH LF ff fp FF _ _ _ _ RF0 FO AP N0 K)].
  Qed.
  Lemma qwin_out_sh : forall W O n x, Forall (qwin hi ff) W -> fsobj H LF O n -> aapp O n -> 0 <= n -> O <= x < O + n -> outside W (sh x).
  Proof.
    induction W as [|[l h] W IH]; intros O n x FW FO AP N0 Hx; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact FO| exact AP| exact N0| exact Hx]].
    pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5). pose proof aceil_facts as (AF1 & _).
    pose proof (sh_below_app x ltac:(lia)) as KH.
    destruct (qwin_fwin _ (Forall_inv FW)) as [K|K]; [cbn [fst snd] in K; unfold AHI_LO in *; clear - K KH AF1; lia| exact (fwin_out_sh HH LF ff fp FF _ _ _ _ _ RF0 FO AP N0 Hx K)].
  Qed.
  Lemma qwin_blk : forall W s LB m p A k, Forall (qwin hi ff) W -> as_RHEAP H s LB m -> In (p, A, k) LB ->
    disjoint_from W A k /\ disjoint_from W (sh A) (nsh k).
  Proof.
    intros W s LB m p A k FW RH IN. pose proof (ah_blocks H HH _ _ _ _ RH IN) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn [blk_addr blk_size fst snd] in *.
    pose proof (fsobj_block H HH _ _ _ LF _ _ _ RH IN) as FO.
    split; [eapply qwin_obj| eapply qwin_obj_sh]; first [exact FW| exact FO| exact R7| lia].
  Qed.
  Lemma qwin_img : forall W A k, Forall (qwin hi ff) W -> A + k <= AIMG_TOP -> disjoint_from W A k.
  Proof.
    induction W as [|[l h] W IH]; intros A k FW HA; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact HA]]. pose proof aceil_facts as (AF1 & _).
    destruct (qwin_fwin _ (Forall_inv FW)) as [K|K]; [cbn [fst snd] in K; left; unfold AIMG_TOP in *; clear - K HA AF1; lia| left; exact (fwin_img LF ff fp FF _ _ _ K HA)].
  Qed.
  Lemma qwin_hi : forall W A k, Forall (qwin hi ff) W -> hi <= A -> disjoint_from W A k.
  Proof.
    induction W as [|[l h] W IH]; intros A k FW HA; cbn; [exact I|].
    split; [| eapply IH; [exact (Forall_inv_tail FW)| exact HA]].
    destruct (qwin_fwin _ (Forall_inv FW)) as [K|K]; [cbn [fst snd] in K; right; clear - K HA; lia|].
    right. assert (Q : aceil <= A) by (clear - HA HI; lia). exact (fwin_stack LF ff fp FF _ A K Q).
  Qed.
  Lemma qwin_fr : forall W, Forall (qwin hi ff) W -> Forall (win_fr ff 32) W.
  Proof.
    intros W FW. eapply Forall_impl; [| exact FW]. intros [l h] K. pose proof aceil_facts as (AF1 & _).
    destruct (qwin_fwin _ K) as [Q|Q]; [cbn [fst snd] in Q; right; left; cbn; unfold AHI_LO in *; clear - Q AF1; lia| exact (fwin_fr LF ff fp FF _ Q)].
  Qed.
  Lemma qwin_client : forall W LB, Forall (qwin hi ff) W -> Forall (aclient_write_ok H LB) W.
  Proof.
    intros W LB FW. eapply Forall_impl; [| exact FW]. intros [l h] K.
    destruct (qwin_fwin _ K) as [Q|Q]; [cbn [fst snd] in Q; left; cbn; clear - Q; lia| exact (fwin_client LF ff fp FF LB _ Q)].
  Qed.
  Lemma qwin_afs : forall W LFx, Forall (qwin hi ff) W -> Forall (afs_write_ok H LFx) W.
  Proof.
    intros W LFx FW. eapply Forall_impl; [| exact FW]. intros [l h] K.
    pose proof (fwin_nums LF ff fp FF) as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & SHFF & SF0 & SF1 & SA & M1 & M2 & LSH & SHH & SIDE & _).
    pose proof (RFS_fsb H HH _ _ RF0) as (B1 & B2 & B3 & B4). pose proof aceil_facts as (AF1 & _).
    left. cbn [fst snd]. destruct K as [K|K]; cbn [fst snd] in K.
    - unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP, AIMG_TOP in *. clear - K B1 B2 AF1. lia.
    - rewrite SHFF in K. unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP, AIMG_TOP, ALOWSH_LO, AHI_LO in *. clear - K SIDE LSH SHH B1. lia.
  Qed.
  Lemma qwin_aconst : forall W, Forall (qwin hi ff) W -> Forall aconst_ok W.
  Proof.
    intros W FW. eapply Forall_impl; [| exact FW]. intros [l h] K. pose proof aceil_facts as (AF1 & _).
    pose proof (fwin_nums LF ff fp FF) as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & SHFF & SF0 & _).
    destruct K as [K|K]; cbn [fst snd] in K.
    - apply aconst_ok_hi. unfold AHI_LO. clear - K AF1. lia.
    - rewrite SHFF in K. pose proof (sh_mono AIMG_TOP ff ltac:(clear - F1; unfold AFS_HDR in F1; lia)) as Q.
      apply aconst_ok_high; [clear - K Q; lia| right; left; clear - K SF0; lia].
  Qed.
  Lemma qwin_stack0 : forall W, Forall (qwin hi ff) W -> Forall stack0_ok W.
  Proof.
    intros W FW. eapply Forall_impl; [| exact FW]. intros [l h] K. pose proof aceil_facts as (AF1 & _).
    destruct (qwin_fwin _ K) as [Q|Q]; [cbn [fst snd] in Q; apply stack0_ok_app; unfold AHI_LO; clear - Q AF1; lia| exact (fwin_stack0 LF ff fp FF _ Q)].
  Qed.
  Lemma qwin_axs : forall W, Forall (qwin hi ff) W -> Forall (fun iv : Z * Z => 0x12a180 <= fst iv \/ snd iv <= 0x119000) W.
  Proof.
    intros W FW. eapply Forall_impl; [| exact FW]. intros [l h] K. pose proof aceil_facts as (AF1 & _).
    pose proof (fwin_nums LF ff fp FF) as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & SHFF & SF0 & _).
    left. cbn [fst snd]. destruct K as [K|K]; cbn [fst snd] in K; [clear - K AF1; lia| rewrite SHFF in K; clear - K SF0; lia].
  Qed.
End QW.

(* [comment removed for export] *)
Lemma RWmF_quiet : asan_rt_hyps H -> forall (C : rsc) (MA : Z) (LFx : list fframe) (w : rsw) (s : as_St H) (errv : word) (Ev : ecv) (m m' me : mem)
    (W : list (Z * Z)) (hi ff fp : Z),
  rs_static H C -> RWp H C MA w -> RWmF C LFx w s errv Ev m ->
  (forall f, In f (c_LF C) -> In f LFx) -> fresh_frame H (c_LF C) 2 ff fp -> as_RFS H (c_LF C) me ->
  aceil <= hi -> hi <= c_bs C ->
  munch W m m' -> wmono bsegs m m' -> mem_inv bsegs m' -> Forall (qwin hi ff) W ->
  RWmF C LFx w s errv Ev m'.
Proof.
  intros HH C MA LFx w s errv Ev m m' me W hi ff fp STC RP RM SUBx FF RF0 HI HB MU WM MI' FW.
  destruct C as [bs fb P E ioc N lo B shi SP stb implb A LBin LF pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp F fc MXc CXc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L ns ls em h u es insz g rdi LBn Ag].
  unfold RWmF, RWp, rs_static in *. cbn_w_all. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A] in *.
  destruct STC as (AOP & AOE & AOF & P8 & E8 & BS8 & FB8 & SEPPE & SEPPF & SEPEF & CEIL & NR & IOC & (p7 & INS) & RBS & INA & SEPAS & LFL4 & LFL1 & TP & MXL & CXL & MB1).
  destruct RP as (PCOK & OWN & MOWN & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62 & AOWN & PERM & FOK & FRL & FRB & FRT & FRM_ & FRF & DJL & DJB0 & DJT & DJM
                  & OFFP & OFFE & STRM & SZS & NRK & CPM & BY & CN & IZ & A0 & AL).
  destruct RM as (PC & UW & HOWN & RDI & J13 & J32a & J8a & J32b & J8b & HCT & FTS & MV & FBU & EC & BSC & SB & HP & ERR & AUX & MI & RF' & AC & SK & ATH & ACP & ACE & SVE & ACB & ACF & SVA).
  set (LB := LBn ++ LBin) in *.
  assert (SUBin : forall b, In b LBin -> In b LB) by (intros b Hb; unfold LB; apply in_or_app; right; exact Hb).
  pose proof aceil_facts as (AF1 & AF2 & AF3).
  pose proof (fwin_nums LF ff fp FF) as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & SHFF & SF0 & SF1 & SA & M1 & M2 & LSH & SHH & SIDE & APFF & APP1 & APB).
  pose proof (aobj_LB_mono _ LB _ _ _ AOP ltac:(intros b [])) as AOPn. pose proof (aobj_LB_mono _ LB _ _ _ AOE ltac:(intros b [])) as AOEn.
  pose proof (aobj_LB_mono _ LB _ _ _ AOF ltac:(intros b [])) as AOFn.
  pose proof (aobj_aapp H HH _ _ _ _ _ _ _ HP RF0 AOPn) as APP0. pose proof (aobj_aapp H HH _ _ _ _ _ _ _ HP RF0 AOEn) as APE. pose proof (aobj_aapp H HH _ _ _ _ _ _ _ HP RF0 AOFn) as APF.
  pose proof (aapp_bounds _ _ APP0 ltac:(clear; lia)) as (Q1 & Q2 & Q3 & Q4 & Q5). pose proof (aapp_bounds _ _ APE ltac:(clear; lia)) as (R1 & R2 & R3 & R4 & R5).
  pose proof (aapp_bounds _ _ APF ltac:(clear; lia)) as (T1 & T2 & T3 & T4 & T5).
  pose proof (aobj_fsobj H HH _ _ _ _ _ _ HP AOPn) as FOP. pose proof (aobj_fsobj H HH _ _ _ _ _ _ HP AOEn) as FOE. pose proof (aobj_fsobj H HH _ _ _ _ _ _ HP AOFn) as FOF.
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF0 FOP FF ltac:(clear - Q4; lia) ltac:(clear; lia) ltac:(clear - Q2 AF1; unfold AAPP_HI in *; lia)) as (DPF & _).
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF0 FOE FF ltac:(clear - R4; lia) ltac:(clear; lia) ltac:(clear - R2 AF1; unfold AAPP_HI in *; lia)) as (DEF & _).
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF0 FOF FF ltac:(clear - T4; lia) ltac:(clear; lia) ltac:(clear - T2 AF1; unfold AAPP_HI in *; lia)) as (DFF & _).
  change (fsz 2) with 256 in DPF, DEF, DFF.
  pose proof (fun O n => qwin_obj HH LF ff fp hi me FF RF0 _ O n FW) as DJO.
  pose proof (fun O n x => qwin_out_sh HH LF ff fp hi me FF RF0 _ O n x FW) as OUS.
  pose proof (fun p0 A0 k0 IN0 => qwin_blk HH LF ff fp hi me FF RF0 _ s LB m p0 A0 k0 FW HP IN0) as DJB.
  pose proof (fun A0 k0 => qwin_img LF ff fp hi FF _ A0 k0 FW) as DJI.
  pose proof (fun A0 k0 => qwin_hi LF ff fp hi FF HI _ A0 k0 FW) as DJH.
  pose proof (qwin_fr LF ff fp hi FF _ FW) as WFR. pose proof (qwin_client LF ff fp hi FF _ LB FW) as WCL.
  cbv beta in DJO, OUS, DJB, DJI, DJH.
  assert (DJP : forall a k, P <= a -> a + k <= P + 352 -> 0 <= k -> disjoint_from W a k).
  { intros a k K1 K2 K3. eapply disjoint_from_sub; [| exact K1| exact K2]. apply DJO; [exact FOP| exact APP0| clear; lia]. }
  assert (OUP : forall x, P <= x < P + 352 -> outside W (sh x)) by (intros x Hx; exact (OUS P 352 x FOP APP0 ltac:(clear; lia) Hx)).
  Local Ltac trw K := eapply (rw_cells_transport bsegs); [exact K| eassumption| eassumption|].
  pose proof (ah_RHEAP_frame H HH _ _ _ _ _ HP MU WM WCL) as HP'.
  pose proof (ah_RFS_frame H HH _ _ _ _ RF' MU WM (qwin_afs HH LF ff fp hi me FF RF0 _ LFx FW)) as RFx.
  pose proof (ACONST_frame _ _ _ AC MU WM (qwin_aconst LF ff fp hi FF _ FW)) as AC'.
  pose proof (stack0_transport _ _ _ _ _ SK MU WM (qwin_stack0 LF ff fp hi FF _ FW)) as SK'.
  assert (F0 : 0 <= ff) by (clear - F1; unfold AIMG_TOP, AFS_HDR in *; lia). assert (F8' : ff mod 8 = 0) by (clear - F3; Z.div_mod_to_equations; lia).
  unfold PutUw in UW |- *. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A] in UW |- *.
  destruct UW as (FC & HDR & USED & MB & RD & MRG & CBH & CBB & PFT & FI & XS2). fold LB.
  split; [trw PC; apply DJP; [clear; lia| cbn; clear; lia| clear; lia]|].
  split.
  { split.
    { eapply AFieldsC_transport_gen; [exact FC| exact MU| exact WM| | |].
      - apply DJP; [clear; lia| cbn; clear; lia| clear; lia].
      - intros x Hx. apply OUP. clear - Hx. lia.
      - intros e dd Ld. destruct (OWN e dd Ld) as (pa & INe & _). exact (DJB _ _ _ INe). }
    split; [trw HDR; apply DJP; [unfold O_PR_HDR; clear; lia| unfold O_PR_HDR; cbn; clear; lia| clear; lia]|].
    split; [trw USED; apply DJP; [unfold O_PR_USED; clear; lia| unfold O_PR_USED; cbn; clear; lia| clear; lia]|].
    split.
    { eapply AMBuf_transport_gen; [exact MB| exact MU| exact WM| | |].
      - apply DJP; [clear; lia| clear; lia| clear; lia].
      - intros x Hx. apply OUP. clear - Hx. lia.
      - intros x s0 IN. destruct (MOWN x s0 IN) as [px INx]. exact (DJB _ _ _ INx). }
    split; [trw RD; apply DJP; [clear; lia| cbn; clear; lia| clear; lia]|].
    split; [trw MRG; apply DJP; [unfold O_PR_MERGE; clear; lia| unfold O_PR_MERGE; cbn; clear; lia| clear; lia]|].
    split; [trw CBH; apply DJP; [clear; lia| cbn; clear; lia| clear; lia]|].
    split; [trw CBB; apply DJP; [clear; lia| cbn; clear; lia| clear; lia]|].
    split; [unfold APfTab in PFT |- *; trw PFT; apply DJI; unfold APF_TABPTR, AIMG_TOP; cbn; clear; lia|].
    split; [eapply FTInit_transport; [exact FI| exact MU| apply DJI; unfold P_A_FT_INIT, AIMG_TOP; clear; lia]|].
    eapply AXStatics2_transport; [exact XS2| exact MU| exact WM| exact (qwin_axs LF ff fp hi FF _ FW)]. }
  assert (K : forall ptr len, ASvOwn LB m ptr len -> ASvOwn LB m' ptr len).
  { intros ptr len [Z0|(L1 & p & bsx & IN & CE & AD)]; [left; exact Z0| right]. split; [exact L1|]. exists p, bsx.
    destruct (DJB _ _ _ IN) as [D1 D2]. split; [exact IN|]. split.
    - trw CE. cbn [cells_size csize Nat.add]. rewrite Nat.add_0_r, Z2Nat.id by (clear - L1; lia). exact D1.
    - eapply addressable_transport; [exact AD| exact MU| exact WM| exact D2]. }
  split; [destruct HOWN as (O1 & O2 & O3 & O4); exact (conj (K _ _ O1) (conj (K _ _ O2) (conj O3 O4)))|]. clear K.
  Local Ltac trj K DJP := eapply (rw_cells_transport bsegs); [exact K| eassumption| eassumption| apply DJP; [clear; lia| cbn; clear; lia| clear; lia]].
  split; [trj RDI DJP|]. split; [trj J13 DJP|]. split; [trj J32a DJP|]. split; [trj J8a DJP|]. split; [trj J32b DJP|]. split; [trj J8b DJP|].
  split; [eapply AHttpCat_transport; [exact HCT| exact MU| exact WM| apply DJI; unfold AG_HTTP_CAT, AIMG_TOP; clear; lia| apply DJI; unfold AG_HTTP_CAT_GUARD, AIMG_TOP; clear; lia]|].
  split; [eapply FTState_transport; [exact FTS| exact MU| exact WM| apply DJI; unfold AG_FIELD_TABLE, AIMG_TOP; clear; lia]|].
  split; [unfold AMiscVt48 in MV |- *; eapply (ro_cells_transport bsegs); [exact MV| exact MU| apply DJI; unfold AW_MISC_CAT_VT48, AW_MISC_CAT_VPTR, AIMG_TOP; cbn; clear; lia]|].
  split.
  { eapply AFlatBuf_transport; [exact FBU| exact MU| exact WM| apply DJO; [exact FOF| exact APF| unfold SZ_FB; clear; lia]| |];
      intros NE; destruct FBU as (_ & FOK' & _); (destruct FOK' as [EFB|(pf & INf & _)]; [exfalso; exact (NE EFB)|]);
      [exact (proj1 (DJB _ _ _ INf))| exact (proj2 (DJB _ _ _ INf))]. }
  split; [trw EC; apply DJO; [exact FOE| exact APE| cbn; clear; lia]|].
  split; [trw BSC; apply DJH; clear - HB; lia|].
  split.
  { destruct (DJB _ _ _ (SUBin _ INS)) as [DSB DSS].
    eapply AStateBlock_transport; [exact SB| exact MU| exact WM| exact DSB| | exact DSS|]; cbn [st_fb];
      intros NEs; (destruct STRM as [[_ ->]|(N1 & SA' & SE)]; [exfalso; exact (NEs eq_refl)|]); unfold fb_cap; rewrite SA', SE;
      destruct (INA N1) as [p9 IN9]; replace (A + N - A) with N by (clear; lia); [exact (proj1 (DJB _ _ _ (SUBin _ IN9)))| exact (proj2 (DJB _ _ _ (SUBin _ IN9)))]. }
  split; [exact HP'|].
  split; [trw ERR; subst tp; unfold errno_addr; rewrite unsigned_lit by (unfold ATP; clear; lia); apply DJI; unfold ATP, AIMG_TOP; cbn; clear; lia|].
  split; [exact (ah_rauxv_frame H HH _ _ _ _ _ AUX MU WM WCL)|]. split; [exact MI'|].
  split; [exact RFx|]. split; [exact AC'|]. split; [exact SK'|]. split; [exact (ah_thr H HH _ _ _ HP')|].
  split; [exact (accessible_transport_fr _ _ _ _ _ ff 32 ACP MU WFR F0 F8' ltac:(clear; lia) ltac:(unfold PARSER_SIZE; clear - DPF; lia))|].
  split; [exact (accessible_transport_fr _ _ _ _ _ ff 32 ACE MU WFR F0 F8' ltac:(clear; lia) ltac:(clear - DEF; lia))|].
  split; [exact (aobj_shvis H HH _ _ _ _ _ _ HP' RFx (aobj_LF_mono _ _ LFx _ _ AOEn SUBx) ltac:(clear; lia))|].
  pose proof (rblock_bounds _ _ RBS) as (SB1 & _). 
  split; [exact (accessible_transport_fr _ _ _ _ _ ff 32 ACB MU WFR F0 F8' ltac:(clear; lia) ltac:(clear - HB HI F2; lia))|].
  split; [exact (accessible_transport_fr _ _ _ _ _ ff 32 ACF MU WFR F0 F8' ltac:(clear; lia) ltac:(clear - DFF; lia))|].
  intros N1. destruct (INA N1) as [p9 IN9]. exact (ah_blk_shvis H HH _ _ _ _ _ _ HP' (SUBin _ IN9)).
Qed.
End HCW.
